const state = { users: [], user: null, authView: 'login', examQuestions: null, tasks: [], notes: [], textbooks: [], exams: [], view: 'dashboard', search: '', history: [], wellness: { active: false, elapsed: 0 }, subject: 'Science', focusMode: false, taskFilter: 'All', modal: null, toast: null, settingsOpen: false, noteType: 'notes', pendingDelete: null, pendingPdf: null, selectedExam: 0, exam: { phase: 'lobby', current: 1, secondsLeft: 30 * 60, startedAt: null, answers: {}, flags: new Set(), results: null }, drill: { open: false, index: 0, flipped: false, ratings: [], complete: false }, settings: { theme: 'paper', sound: true, ai: true } };
