const esc = (value) => String(value ?? '').replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char]));
const scopedKey = (key) => state.user ? `${key}:${state.user.username}` : key;
const getStore = (key, fallback) => { try { const value = JSON.parse(localStorage.getItem(scopedKey(key))); return value ?? fallback; } catch { return fallback; } };
const saveStore = (key, value) => localStorage.setItem(scopedKey(key), JSON.stringify(value));
const userApi = (endpoint) => `${endpoint}${endpoint.includes('?') ? '&' : '?'}user=${encodeURIComponent(state.user?.username || '')}`;
const subjectAccent = (subject) => SUBJECT_CLASS[subject] || 'ink';
const formatDeadline = (deadline) => { const date = new Date(`${deadline}T00:00:00`); return Number.isNaN(date.getTime()) ? deadline : new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short' }).format(date); };
const todayString = () => { const now = new Date(); const local = new Date(now.getTime() - now.getTimezoneOffset() * 60000); return local.toISOString().slice(0, 10); };
const todayLabel = () => new Intl.DateTimeFormat('en-US', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date()).toUpperCase();
const examCountdown = () => { const now = new Date(); const target = new Date(2026, 9, 22, 9, 0, 0); const hoursLeft = Math.max(0, Math.floor((target.getTime() - now.getTime()) / 3600000)); return `${Math.floor(hoursLeft / 24)}d ${String(hoursLeft % 24).padStart(2, '0')}h`; };
const parseCsv = (text) => { const rows = []; let row = [], cell = '', quoted = false; for (let i = 0; i < text.length; i += 1) { const ch = text[i]; if (quoted && ch === '"' && text[i + 1] === '"') { cell += '"'; i += 1; } else if (ch === '"') quoted = !quoted; else if (ch === ',' && !quoted) { row.push(cell); cell = ''; } else if ((ch === '\n' || ch === '\r') && !quoted) { if (ch === '\r' && text[i + 1] === '\n') i += 1; row.push(cell); if (row.some((value) => value !== '')) rows.push(row); row = []; cell = ''; } else cell += ch; } if (cell || row.length) { row.push(cell); rows.push(row); } const [headers, ...data] = rows; return data.filter((values) => values[0]).map((values) => Object.fromEntries(headers.map((header, index) => [header, values[index] ?? '']))); };
const formatTime = (seconds) => `${String(Math.max(0, Math.floor(seconds / 60))).padStart(2, '0')}:${String(Math.max(0, seconds % 60)).padStart(2, '0')}`;
